# Insilos Sovereign OS — Layer 1: Sovereign Industrial SCADA & Anomaly FFT from insilos.scada import OPCUAClient, SensorStream, AnomalyDetector from insilos.security import MerkleAirGapValidator
@pipeline(layer="SCADA_L1", frequency_hz=50.0, airgap_enforced=True) async def ingest_high_frequency_telemetry(node_id: str = "ENERGY_TURBINE_04"): client = OPCUAClient.connect(endpoint="opc.tcp://10.24.8.1:4840", tls_cert="/etc/insilos/pki/hsm.crt") stream = client.subscribe_telemetry(metrics=["vibration_rms", "stator_temp", "oil_pressure"])
async for packet in stream: # Validate cryptographic Merkle root hash on inbound sensor frames MerkleAirGapValidator.verify_packet_hash(packet)
# Real-time Fast Fourier Transform (FFT) vibration harmonic detection fft_spectrum = AnomalyDetector.spectral_fft(packet.vibration_rms) if fft_spectrum.harmonic_peak > 4.25: # Exceeds ISO 10816 severe threshold await emit_event("CRITICAL_VIBRATION_DETECTED", payload=packet.to_dict()) return {"status": "DISPATCH_REQUIRED", "target_layer": "L4_FSM", "latency_ms": 11.8}

# Insilos Sovereign OS — Layer 2: Vertical IDP & WCO SAFE Trade Engine from insilos.idp import MultimodalParser, CustomsRuleEngine from insilos.compliance import EVFTA_Matrix, VNACCS_Reconciler
@agent_action(layer="IDP_L2", accuracy_sla=0.998, max_latency_sec=3.2) def process_customs_dossier(dossier_pdf: bytes, bl_number: str) -> dict: # Multimodal OCR Extraction (Bill of Lading, Commercial Invoice, Packing List) extracted = MultimodalParser.extract(dossier_pdf, schema="VNACCS_E_CUSTOMS_V4")
# 3-Way Cross-Reconciliation against ERP Purchase Order & Port Ledger reconciliation = VNACCS_Reconciler.match_triad( bill_of_lading=extracted.get("bill_of_lading"), invoice_items=extracted.get("line_items"), erp_po_ref="PO-2026-8891" ) assert reconciliation.variance == 0.0, "Discrepancy detected in customs valuation"
# Validate Rules of Origin & HS Code under EVFTA Annex II compliance_proof = EVFTA_Matrix.validate_co_origin(extracted.hs_code, origin_country="VN") return { "status": "STRAIGHT_THROUGH_PROCESSED", "hs_code": extracted.hs_code, "preferential_tariff": compliance_proof.duty_rate, "processing_time_sec": 0.382 }

# Insilos Sovereign OS — Layer 4: Intelligent FSM Dispatch & Zero-Downtime from insilos.fsm import DispatchEngine, MobileFieldHub from insilos.erp import ERPConnector
@workflow(layer="FSM_L4", target_sla_minutes=45) def orchestrate_predictive_repair(alert_event: dict): # Match best technician by certifications (IEC 61850), live GPS & van inventory assigned_tech = DispatchEngine.find_optimal_technician( required_cert="HIGH_VOLTAGE_SPECIALIST_L3", required_parts=["BEARING_SKF_6314_2RS1"], max_eta_minutes=60 )
# Auto-generate ERP Work Order & Reserved Spares in SAP/Insilos Core work_order = ERPConnector.create_maintenance_order( asset_id=alert_event["asset_id"], technician_id=assigned_tech.id, urgency="HIGH_PRIORITY_PREDICTIVE" )
# Push encrypted job pack to field engineer's mobile device MobileFieldHub.push_job(assigned_tech.device_id, work_order.pack) return {"work_order_id": work_order.number, "ftfr_probability": 0.948, "status": "DISPATCHED"}

main.script:
document.addEventListener('DOMContentLoaded', function() {
    // --- 1. Interactive Multi-Slider ROI Calculator ---
    var sliderErp = document.getElementById('ins-calc-erp');
    var sliderVol = document.getElementById('ins-calc-volume');
    var sliderErr = document.getElementById('ins-calc-error');
    var displayErp = document.getElementById('ins-calc-val-erp-display');
    var displayVol = document.getElementById('ins-calc-val-vol-display');
    var displayErr = document.getElementById('ins-calc-val-err-display');
    var netSavingsEl = document.getElementById('ins-calc-net-savings');
    var hoursSavedEl = document.getElementById('ins-calc-hours-saved');
    var paybackMonthsEl = document.getElementById('ins-calc-payback-months');
    var currButtons = document.querySelectorAll('.ins-calc-curr-btn');

    var currentCurrency = 'VND';
    var VND_PER_USD = 25000;

    function updateROI() {
        var erp = sliderErp ? parseInt(sliderErp.value, 10) : 4;
        var vol = sliderVol ? parseInt(sliderVol.value, 10) : 25000;
        var errRate = sliderErr ? parseFloat(sliderErr.value) : 3.8;

        if (displayErp) displayErp.textContent = erp + ' ERPs';
        if (displayVol) displayVol.textContent = vol.toLocaleString('vi-VN') + ' Tài Liệu';
        if (displayErr) displayErr.textContent = errRate.toFixed(1) + '%';

        var monthlyHours = vol * 0.2375;
        var annualHours = Math.round(monthlyHours * 12);

        var monthlyErrorsAvoided = vol * (errRate / 100) * 0.98;
        var monthlyErrorCostVND = monthlyErrorsAvoided * 400000;
        var monthlyLaborVND = (vol * 5000) + (erp * 15000000);
        var monthlyTotalVND = monthlyLaborVND + monthlyErrorCostVND;
        var annualSavingsVND = monthlyTotalVND * 12;

        var payback = monthlyTotalVND > 0 ? (1800000000 / monthlyTotalVND) : 3.2;
        if (payback < 1.2) payback = 1.2;
        if (payback > 8.5) payback = 8.5;

        if (hoursSavedEl) {
            hoursSavedEl.textContent = annualHours.toLocaleString('vi-VN') + ' Giờ / Năm';
        }
        if (paybackMonthsEl) {
            paybackMonthsEl.textContent = payback.toFixed(1) + ' Tháng';
        }

        if (netSavingsEl) {
            if (currentCurrency === 'VND') {
                if (annualSavingsVND >= 1000000000) {
                    var billions = (annualSavingsVND / 1000000000).toFixed(2);
                    netSavingsEl.textContent = '₫' + billions + ' Tỷ / Năm';
                } else {
                    netSavingsEl.textContent = '₫' + Math.round(annualSavingsVND).toLocaleString('vi-VN') + ' / Năm';
                }
            } else {
                var annualSavingsUSD = annualSavingsVND / VND_PER_USD;
                netSavingsEl.textContent = '$' + Math.round(annualSavingsUSD).toLocaleString('en-US') + ' / Year';
            }
        }
    }

    if (sliderErp) sliderErp.addEventListener('input', updateROI);
    if (sliderVol) sliderVol.addEventListener('input', updateROI);
    if (sliderErr) sliderErr.addEventListener('input', updateROI);

    currButtons.forEach(function(btn) {
        btn.addEventListener('click', function() {
            currButtons.forEach(function(b) { b.classList.remove('active'); });
            btn.classList.add('active');
            currentCurrency = btn.getAttribute('data-currency') || 'VND';
            updateROI();
        });
    });

    updateROI();

    // --- 2. Tech Proof Animated Stats Counters ---
    var counterElements = document.querySelectorAll('.ins-counter');
    if ('IntersectionObserver' in window && counterElements.length > 0) {
        var counterObserver = new IntersectionObserver(function(entries, observer) {
            entries.forEach(function(entry) {
                if (entry.isIntersecting) {
                    var el = entry.target;
                    observer.unobserve(el);

                    var target = parseFloat(el.getAttribute('data-counter-target'));
                    var prefix = el.getAttribute('data-counter-prefix') || '';
                    var suffix = el.getAttribute('data-counter-suffix') || '';
                    var decimals = parseInt(el.getAttribute('data-counter-decimals') || '0', 10);
                    var duration = 1600;
                    var startTime = null;

                    function step(timestamp) {
                        if (!startTime) startTime = timestamp;
                        var progress = Math.min((timestamp - startTime) / duration, 1);
                        var ease = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
                        var current = target * ease;
                        el.textContent = prefix + current.toFixed(decimals) + suffix;
                        if (progress < 1) {
                            window.requestAnimationFrame(step);
                        } else {
                            el.textContent = prefix + target.toFixed(decimals) + suffix;
                        }
                    }
                    window.requestAnimationFrame(step);
                }
            });
        }, { threshold: 0.3 });

        counterElements.forEach(function(el) {
            counterObserver.observe(el);
        });
    }
});
